<?php $result = $result ?? ['items' => [], 'page' => 1, 'pages' => 1, 'total' => 0]; ?>
<section class="card"><div class="card-header"><div><h2>برنامه اقساط</h2><p class="text-muted"><?= to_persian_digits($result['total'] ?? 0) ?> قسط</p></div></div><div class="table-wrap"><table><thead><tr><th scope="col">قرارداد</th><th scope="col">قسط</th><th scope="col">سررسید</th><th scope="col">اصل باقی‌مانده</th><th scope="col">قابل پرداخت امروز</th><th scope="col">وضعیت</th><th scope="col"></th></tr></thead><tbody>
<?php foreach (($result['items'] ?? []) as $item): ?><tr><td><?= e($item['contract_number'] ?? '') ?></td><td><?= to_persian_digits($item['installment_number'] ?? '') ?></td><td><?= e(jdate($item['due_date'] ?? '')) ?></td><td><?= money_toman(max(0, (int) ($item['base_amount'] ?? 0) - (int) ($item['paid_amount'] ?? 0))) ?></td><td><?= money_toman($item['payable'] ?? $item['base_amount'] ?? 0) ?></td><td><span class="badge <?= e(badge_class($item['status'] ?? '')) ?>"><?= e(status_label($item['status'] ?? '')) ?></span></td><td><a class="btn small secondary" href="<?= e(url('contracts/show/' . (int) ($item['contract_id'] ?? 0) . '#contract-installments')) ?>">قرارداد</a></td></tr><?php endforeach; ?>
